            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If both are None, they're equal
        if pre1 is None and pre2 is None:
            return 0
        # Version without pre-release sorts after version with pre-release
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare identifier by identifier
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

