                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_digit1:
                # All-digit identifier sorts before non-digit
                return -1
            elif is_digit2:
                # Non-digit identifier sorts after all-digit
                return 1
            else:
                # Both are non-digit, compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

    def sort_key(v):
        parsed = parse_version(v)
        major, minor, patch, prerelease = parsed

        # Create a tuple for sorting
        # We need to handle pre-release comparison carefully
        # Return (major, minor, patch, prerelease_sort_key)
        if prerelease is None:
            # No pre-release sorts after pre-release, so use (1,) as indicator
            return (major, minor, patch, 1, [])
