            # With pre-release sorts first, so use (0,) as indicator
            # Also need to create a comparable key for prerelease identifiers
            prerelease_key = []
            for identifier in prerelease:
                if identifier.isdigit():
                    # All-digit: (0, numeric_value)
                    prerelease_key.append((0, int(identifier)))
                else:
                    # Non-digit: (1, string_value)
                    prerelease_key.append((1, identifier))
            return (major, minor, patch, 0, prerelease_key)

